CREATE FUNCTION public.add_business_days(ts timestamp without time zone, n integer) RETURNS timestamp without time zone
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    d date := ts::date;
    cnt integer := 0;
BEGIN
    WHILE cnt < n LOOP
        d := d + 1;
        IF EXTRACT(DOW FROM d) NOT IN (0, 6) THEN
            cnt := cnt + 1;
        END IF;
    END LOOP;
    RETURN d + (ts - ts::date);
END;
$$;


