-- Name: v_attestation_ml; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_attestation_ml AS
 SELECT ta.id AS assignment_id,
    ta.task_id,
    ta.developer_id,
    ta.developer_role_id,
    ta.assigned_at,
    ta.due_at,
    ta.completed_at,
        CASE
            WHEN (ta.due_at IS NOT NULL) THEN ta.due_at
            WHEN ((dr.slug)::text = 'qa'::text) THEN public.add_business_days(ta.assigned_at, 3)
            ELSE NULL::timestamp without time zone
        END AS effective_due_at,
    round((EXTRACT(epoch FROM (ta.completed_at - ta.assigned_at)) / (3600)::numeric), 2) AS hours_to_complete,
    round((EXTRACT(epoch FROM (COALESCE(ta.due_at, public.add_business_days(ta.assigned_at, 3)) - ta.assigned_at)) / (86400)::numeric), 2) AS allowed_days,
        CASE
            WHEN ((ta.completed_at IS NOT NULL) AND (((ta.due_at IS NOT NULL) AND (ta.completed_at > ta.due_at)) OR ((ta.due_at IS NULL) AND ((dr.slug)::text = 'qa'::text) AND (ta.completed_at > public.add_business_days(ta.assigned_at, 3))))) THEN 1
            ELSE 0
        END AS is_sla_breached,
    round(GREATEST((EXTRACT(epoch FROM (ta.completed_at - COALESCE(ta.due_at, public.add_business_days(ta.assigned_at, 3)))) / (3600)::numeric), (0)::numeric), 2) AS hours_overdue,
    tt.slug AS task_type,
    t.priority,
    t.story_points,
    t.estimated_hours,
    t.sprint_id,
    ws.slug AS workflow_status,
    d.experience_years,
    el.name AS education_level,
    dr.slug AS developer_role,
    t.project_id,
    p.name AS project_name,
    p.code AS project_code,
    p.organization_id,
    o.name AS organization_name,
    o.industry,
    ( SELECT count(*) AS count
           FROM public.task_assignments ta2
          WHERE (ta2.task_id = ta.task_id)) AS assignments_on_task,
    (EXISTS ( SELECT 1
           FROM (public.task_label_assignments tla
             JOIN public.labels l ON ((l.id = tla.label_id)))
          WHERE ((tla.task_id = ta.task_id) AND ((l.slug)::text = 'high_priority'::text) AND (tla.is_active = true)))) AS has_high_priority
   FROM ((((((((public.task_assignments ta
     JOIN public.tasks t ON ((t.id = ta.task_id)))
     JOIN public.task_types tt ON ((tt.id = t.task_type_id)))
     JOIN public.workflow_statuses ws ON ((ws.id = t.workflow_status_id)))
     JOIN public.developers d ON ((d.id = ta.developer_id)))
     JOIN public.education_levels el ON ((el.id = d.education_level_id)))
     JOIN public.developer_roles dr ON ((dr.id = ta.developer_role_id)))
     JOIN public.projects p ON ((p.id = t.project_id)))
     JOIN public.organizations o ON ((o.id = p.organization_id)))
  WHERE ((ta.completed_at IS NOT NULL) AND ((ta.due_at IS NOT NULL) OR ((dr.slug)::text = 'qa'::text)));


