        END AS is_sla_breached,
        CASE
            WHEN (ta.completed_at IS NOT NULL) THEN GREATEST((EXTRACT(epoch FROM (ta.completed_at - COALESCE(ta.due_at, public.add_business_days(ta.assigned_at, 3)))) / (3600)::numeric), (0)::numeric)
            ELSE NULL::numeric
        END AS hours_overdue,
    t.task_type_id,
    tt.slug AS task_type,
    t.priority,
    t.story_points,
    t.estimated_hours,
    t.sprint_id,
    ws.slug AS workflow_status,
    d.experience_years,
    el.name AS education_level,
    dr.slug AS developer_role,
    o.industry,
    o.name AS organization_name,
    ( SELECT count(*) AS count
           FROM public.task_assignments ta2
          WHERE (ta2.task_id = ta.task_id)) AS assignments_on_task,
    (EXISTS ( SELECT 1
           FROM (public.task_label_assignments tla
             JOIN public.labels l ON ((l.id = tla.label_id)))
          WHERE ((tla.task_id = ta.task_id) AND ((l.slug)::text = 'high_priority'::text) AND (tla.is_active = true)))) AS has_high_priority
   FROM ((((((((public.task_assignments ta
     JOIN public.tasks t ON ((t.id = ta.task_id)))
     JOIN public.task_types tt ON ((tt.id = t.task_type_id)))
     JOIN public.workflow_statuses ws ON ((ws.id = t.workflow_status_id)))
     JOIN public.developers d ON ((d.id = ta.developer_id)))
     JOIN public.education_levels el ON ((el.id = d.education_level_id)))
     JOIN public.developer_roles dr ON ((dr.id = ta.developer_role_id)))
     JOIN public.projects p ON ((p.id = t.project_id)))
     JOIN public.organizations o ON ((o.id = p.organization_id)))
  WHERE ((ta.completed_at IS NOT NULL) AND ((ta.due_at IS NOT NULL) OR ((dr.slug)::text = 'qa'::text)));


